/**
 * ───────────────────────────────────────────────────────────────────────────────
 * [shadcn registry item · 教学演示件] AI 思考中指示器 AI Thinking Indicator
 *
 * 来源:uiux-atlas src/content/entries/components/ai-thinking-indicator/demo/Demo.tsx
 *       (由 scripts/generate-registry.mjs 内联生成;源文件保持不动,重跑生成器即刷新)
 *
 * 诚实标注:这是教学演示件,不是生产组件。原 demo 依赖的三个 @/ 内部模块
 * (@/lib/store 参数 store、@/lib/types 类型、@/components/DemoStage 演示舞台)
 * 在 registry 消费端不可用,已原位改写为「[registry 改写]」注释;文件体内对应的
 * getEntryStore / EntrySchema / DemoStage 引用需按各注释提示替换后,本文件才可编译运行。
 * 它记录的是「本站条目页如何实时驱动参数」,供阅读与改写,不可直接安装即用。
 *
 * 依赖:仅 react(+宿主的 react-dom 渲染);registry item 的 dependencies 留空,
 * 由消费端项目按自身版本声明 react。
 * ───────────────────────────────────────────────────────────────────────────────
 */
import { useEffect, useRef, useState } from "react";
// [registry 改写] 原:import { getEntryStore } from "@/lib/store"; —— 本站内部参数 store(getEntryStore,演示页参数面板 → 舞台的实时数据源),registry 消费端不可用;接入时请改为本地受控 state(useState + props),文件体内的 getEntryStore / store.get / store.subscribe 调用需同步替换。
// [registry 改写] 原:import type { EntrySchema } from "@/lib/types"; —— 本站条目 schema 的 TS 类型(EntrySchema),registry 消费端不可用;接入时请以你自己的参数定义类型内联替代,文件体内的 EntrySchema 注解需同步替换。
// [registry 改写] 原:import DemoStage from "@/components/DemoStage"; —— 本站演示舞台组件(.demo-stage:cssVar 注入点 + 舞台铭牌 + #s= 分享参数恢复),registry 消费端不可用;接入时请以自有舞台容器(如一个 <div>)替代,文件体内的 <DemoStage> 标签需同步替换。

interface DemoProps {
  entryId: string;
  schema: EntrySchema;
}

/* 思考步骤脚本:与 AI Elements ChainOfThought 的 complete|active|pending 状态机同构,
   >10s 档用「步骤 4/5 + Stop」表达 percent-done 语义(调研 15§3.2/§3.3)。 */
const STEPS = [
  { zh: "解析问题与约束", en: "Parsing the question and constraints", ms: 1400 },
  { zh: "检索相关规范条目", en: "Retrieving relevant spec entries", ms: 2200 },
  { zh: "比对三套官方数值", en: "Comparing three official value sets", ms: 3400 },
  { zh: "整理结论与出处", en: "Organizing conclusions and sources", ms: 2600 },
  { zh: "撰写最终回答", en: "Drafting the final answer", ms: 1500 },
];

type Phase = "submitted" | "thinking" | "done";

const css = `
.sti-wrap { width: min(560px, calc(100% - 24px)); position: relative; }
.sti-card {
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--bg-elev);
  padding: 14px 18px;
  min-height: 200px;
}
.sti-q { margin: 0 0 10px; font-size: 13px; color: var(--text-dim, var(--text-1)); }
.sti-q strong { color: var(--text-1); }
.sti-head {
  display: flex; align-items: center; gap: 10px;
  width: 100%; border: 0; background: none; padding: 0;
  font: inherit; font-size: 13px; color: var(--text-1);
  cursor: pointer; text-align: left;
}
.sti-head:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 6px; }
.sti-chev { transition: rotate 0.2s ease; color: var(--text-faint); }
.sti-head[aria-expanded="true"] .sti-chev { rotate: 90deg; }
/* shimmer 思考标签:text-transparent + background-clip:text 渐变扫光(vercel/chatbot 同型) */
.sti-shimmer {
  background-image: linear-gradient(90deg, var(--text-faint) 42%, var(--text-1) 50%, var(--text-faint) 58%);
  background-size: calc(200% * var(--sti-spread, 2)) 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: sti-sweep var(--sti-shimmer-ms, 2000ms) linear infinite;
}
@keyframes sti-sweep { from { background-position: 100% 0; } to { background-position: -100% 0; } }
/* 三点脉冲:submitted 空档(AI SDK 官方形态家族) */
.sti-dots { display: inline-flex; gap: 5px; align-items: center; }
.sti-dots i {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--accent);
  animation: sti-pulse 1.2s ease-in-out infinite;
}
.sti-dots i:nth-child(2) { animation-delay: 0.15s; }
.sti-dots i:nth-child(3) { animation-delay: 0.3s; }
@keyframes sti-pulse { 0%, 70%, 100% { opacity: 0.25; } 35% { opacity: 1; } }
/* spinner:submitted 档另一形态 */
.sti-spin {
  width: 14px; height: 14px; border-radius: 50%;
  border: 2px solid color-mix(in srgb, var(--accent) 30%, transparent);
  border-top-color: var(--accent);
  animation: sti-rotate 0.9s linear infinite;
}
@keyframes sti-rotate { to { rotate: 360deg; } }
/* 步骤卡:complete | active | pending(AI Elements ChainOfThought 状态机) */
.sti-steps { margin: 10px 0 0; padding: 0; list-style: none; font-size: 12.5px; color: var(--text-1); }
.sti-steps li { display: flex; gap: 8px; padding: 4px 0; align-items: baseline; }
.sti-dot { width: 8px; height: 8px; border-radius: 50%; flex: none; translate: 0 1px; }
.sti-steps li[data-state="done"] .sti-dot { background: var(--accent); }
.sti-steps li[data-state="active"] .sti-dot {
  background: color-mix(in srgb, var(--accent) 35%, transparent);
  box-shadow: inset 0 0 0 2px var(--accent);
}
.sti-steps li[data-state="pending"] { color: var(--text-faint); }
.sti-steps li[data-state="pending"] .sti-dot { background: var(--border); }
.sti-steps li[data-state="done"] { color: var(--text-dim, var(--text-1)); }
.sti-count { margin-left: auto; font-family: var(--font-mono, ui-monospace, monospace); font-size: 11px; color: var(--text-faint); }
.sti-elapsed { font-family: var(--font-mono, ui-monospace, monospace); font-size: 11px; color: var(--text-faint); }
.sti-foot { display: flex; align-items: center; gap: 10px; margin-top: 12px; }
.sti-status { margin: 0; font-size: 12px; color: var(--text-faint); }
.sti-stop {
  margin-left: auto;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--bg-elev);
  color: var(--text-1);
  font: inherit; font-size: 12px;
  padding: 4px 12px;
  cursor: pointer;
}
.sti-stop:hover { border-color: var(--accent); color: var(--accent); }
.sti-stop:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.sti-tools { position: absolute; right: -4px; top: -38px; display: flex; gap: 6px; }
.sti-tools button {
  border: 1px solid var(--border); border-radius: 999px;
  background: var(--bg-elev); color: var(--text-1);
  font: inherit; font-size: 12px; padding: 4px 12px; cursor: pointer;
}
.sti-tools button:hover { border-color: var(--accent); color: var(--accent); }
.sti-tools button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.sti-hint { margin: 8px 2px 0; font-size: 12px; color: var(--text-faint); }
@media (prefers-reduced-motion: reduce) {
  .sti-shimmer {
    animation: none;
    background: none;
    -webkit-background-clip: initial;
    background-clip: initial;
    color: var(--text-dim, var(--text-1));
  }
  .sti-dots i, .sti-spin { animation: none; }
}
`;

/**
 * AI 思考中指示器演示:submitted 空档(三点/Spinner)→ 思考段(shimmer + 步骤卡)→
 * 完成自动收起 + 用时读数。pendingIndicator / autoOpenOnStream / stopVisible 为 JS 型参数
 * (订阅 store);shimmerDurationMs 为 CSS 变量型(--sti-shimmer-ms,经 DemoStage 注入);
 * shimmerSpread 参与 inline 变量 --sti-spread;stepAutoCollapseMs 为 JS 计时。
 * 步骤总时长 ≈ 11.1s:>10s 档,NN/g 第三限的 Stop 按钮必须可见。
 */
export default function Demo({ entryId, schema }: DemoProps) {
  const store = getEntryStore(entryId, schema);
  const [pendingIndicator, setPendingIndicator] = useState(() => store.get("pendingIndicator") as string);
  const [spread, setSpread] = useState(() => store.get("shimmerSpread") as number);
  const [autoCollapseMs, setAutoCollapseMs] = useState(() => store.get("stepAutoCollapseMs") as number);
  const [autoOpen, setAutoOpen] = useState(() => store.get("autoOpenOnStream") as string);
  const [stopVisible, setStopVisible] = useState(() => store.get("stopVisible") as string);

  const [runId, setRunId] = useState(0);
  const [phase, setPhase] = useState<Phase>("submitted");
  const [activeStep, setActiveStep] = useState(-1);
  const [elapsed, setElapsed] = useState(0);
  const [open, setOpen] = useState(false);
  const [collapsedOnce, setCollapsedOnce] = useState(false);
  const startRef = useRef(0);

  useEffect(
    () =>
      store.subscribe(() => {
        setPendingIndicator(store.get("pendingIndicator") as string);
        setSpread(store.get("shimmerSpread") as number);
        setAutoCollapseMs(store.get("stepAutoCollapseMs") as number);
        setAutoOpen(store.get("autoOpenOnStream") as string);
        setStopVisible(store.get("stopVisible") as string);
      }),
    [store],
  );

  const replay = () => {
    setRunId((n) => n + 1);
    setPhase("submitted");
    setActiveStep(-1);
    setElapsed(0);
    setCollapsedOnce(false);
    setOpen(false);
  };

  // 状态机:submitted(600ms 空档)→ thinking(逐级点亮步骤)→ done(收起 + 读数)
  useEffect(() => {
    startRef.current = Date.now();
    const timers: number[] = [];
    timers.push(window.setTimeout(() => setPhase("thinking"), 600));
    let t = 600;
    STEPS.forEach((s, i) => {
      t += s.ms;
      timers.push(
        window.setTimeout(() => {
          setActiveStep(i + 1 < STEPS.length ? i + 1 : STEPS.length);
          setElapsed(Math.ceil((Date.now() - startRef.current) / 1000));
        }, t),
      );
    });
    timers.push(
      window.setTimeout(() => {
        setPhase("done");
        setElapsed(Math.ceil((Date.now() - startRef.current) / 1000));
      }, t + 300),
    );
    return () => timers.forEach((id) => window.clearTimeout(id));
  }, [runId]);

  // 流开始自动展开(defaultOpen ?? isStreaming 语义);done 后按 AUTO_CLOSE_DELAY 自动收起(仅一次)
  useEffect(() => {
    if (phase === "thinking" && autoOpen === "on") setOpen(true);
    if (phase === "done" && autoCollapseMs > 0 && !collapsedOnce) {
      const id = window.setTimeout(() => {
        setOpen(false);
        setCollapsedOnce(true);
      }, autoCollapseMs);
      return () => window.clearTimeout(id);
    }
  }, [phase, autoOpen, autoCollapseMs, collapsedOnce]);

  const totalMs = STEPS.reduce((n, s) => n + s.ms, 0);
  const thinking = phase === "submitted" || phase === "thinking";
  const busy = thinking ? "true" : "false";
  const status =
    phase === "submitted"
      ? "已发出、等流开始 submitted — loading dots / spinner"
      : phase === "thinking"
        ? `思考中 Thinking… 步骤 ${Math.max(activeStep, 0)}/${STEPS.length} · ${elapsed}s`
        : `已完成 Done · Thought for ${Math.max(elapsed, 1)} seconds`;

  return (
    <DemoStage entryId={entryId} schema={schema}>
      <div className="sti-wrap">
        <div className="sti-tools" role="group" aria-label="演示控制 Demo controls">
          <button type="button" onClick={replay}>重播 Replay</button>
        </div>
        <div className="sti-card" aria-busy={busy}>
          <p className="sti-q"><strong>问:</strong> 三大设计体系的响应时间规范有什么差异?</p>
          <button
            type="button"
            className="sti-head"
            aria-expanded={open}
            aria-controls="sti-steps"
            onClick={() => setOpen((o) => !o)}
          >
            <span className="sti-chev" aria-hidden="true">▸</span>
            {phase === "submitted" ? (
              <>
                {pendingIndicator === "dots" && (
                  <span className="sti-dots" aria-hidden="true"><i /><i /><i /></span>
                )}
                {pendingIndicator === "spinner" && <span className="sti-spin" aria-hidden="true" />}
                <span>正在连接…</span>
              </>
            ) : phase === "thinking" ? (
              <>
                <span className="sti-shimmer" style={{ ["--sti-spread" as string]: String(spread) }}>
                  Thinking…
                </span>
                <span className="sti-elapsed">{elapsed}s</span>
              </>
            ) : (
              <>
                <span>Thought for {Math.max(elapsed, 1)} seconds</span>
                <span className="sti-elapsed">已收起 collapsed once</span>
              </>
            )}
          </button>
          <ul id="sti-steps" className="sti-steps" hidden={!open}>
            {STEPS.map((s, i) => {
              const state =
                phase === "done" || i < activeStep ? "done" : i === activeStep ? "active" : "pending";
              return (
                <li key={s.en} data-state={state}>
                  <span className="sti-dot" aria-hidden="true" />
                  <span>{s.zh} {s.en}</span>
                  {(phase === "done" || i < activeStep) && (
                    <span className="sti-count" aria-hidden="true">done</span>
                  )}
                </li>
              );
            })}
          </ul>
          <div className="sti-foot">
            <p className="sti-status" aria-live="polite">{status}</p>
            {stopVisible === "on" && thinking && (
              <button type="button" className="sti-stop" onClick={() => setPhase("done")}>
                停止 Stop
              </button>
            )}
          </div>
        </div>
        <p className="sti-hint">
          全程约 {Math.round(totalMs / 1000)}s(&gt;10s 档):注意 1s 后才出现 shimmer/三点、结束时 1s 自动收起并留下用时读数 ·
          Steps span ~{Math.round(totalMs / 1000)}s (&gt;10s tier): shimmer/dots appear past 1s, auto-collapse 1s after done
        </p>
      </div>
      <style>{css}</style>
    </DemoStage>
  );
}
